insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (11, 2, 1, $t$Compreendendo a Visão Celular$t$, $t$De fato, sem fé é impossível agradar a Deus, porquanto é necessário que aquele que se aproxima de Deus creia que ele existe e que se torna galardoador dos que o buscam.$t$, $t$Hebreus 11:6$t$, $j$[{"titulo": "Introdução", "texto": "A Visão Celular é uma estratégia de crescimento e de multiplicação do Reino de Jesus na Terra (Is 9:7; 54:3; 55:5; 60:22). Nascida no coração de Deus, tem como objetivo fazer de cada membro do corpo de Cristo um discípulo líder, pois o IDE de Jesus não foi dado apenas aos pastores e missionários, mas a “todos quantos O receberam” (Jo 1:12). Só Deus dá o crescimento (1Co 3:7)."}, {"titulo": "1. O que é a Visão Celular?", "texto": "Como estratégia para a restauração de vidas, a Visão se estabelece por quatro princípios:", "itens": ["GANHAR – caracterizado pelo EVANGELISMO pessoal, maciço e/ou congregacional (1Co 9:16; Lc 17:10)", "CONSOLIDAR – caracterizado pela CONSERVAÇÃO do fruto conquistado, através da atenção e dedicação", "DISCIPULAR – caracterizado pelo ENSINO (2Tm 2:2): só ensinamos outros quando o caráter de Cristo já está em nós", "ENVIAR – caracterizado pelo IDE de Jesus (Mt 28:19): o discípulo pronto para se reproduzir em outros (Mt 9:37)"], "ref": "Mt 28:19"}, {"titulo": "Alguns propósitos do discipulado", "itens": ["Transmitir o Evangelho a discípulos fiéis, para que conheçam, guardem e ensinem a fé bíblica (2Tm 3:14-15)", "Levar os discípulos a viverem em santidade de vida (1Pe 1:13-25)", "Mostrar a necessidade de batalhar pela fé que uma vez foi dada aos santos (Jd 3)", "Preparar o discípulo para fortalecer outros na célula e levá-los à maturidade (Ef 4:11-16)", "Conduzir a uma experiência mais profunda do Reino de Deus e do conflito contra Satanás (Ef 6:10-18)", "Levar ao batismo no Espírito Santo, a orar, jejuar e adorar (At 2:4)", "Motivar a dedicar-se sem reservas à evangelização dos perdidos (Mt 28:18-20; Mc 16:15-20)"]}, {"titulo": "2. Para que a Visão Celular?", "texto": "Assim como as células se multiplicam, a Visão Celular nasceu para que, juntos, possamos multiplicar discípulos para o Senhor Jesus não só em nossa nação, mas em todas as nações (etnias) da terra. A tarefa do IDE é a razão maior da permanência da Igreja neste mundo."}, {"titulo": "Implicações do IDE para a igreja celular", "itens": ["Privilégio – anunciar o Evangelho é privilégio de quem foi justificado pelo sangue de Cristo (1Pe 1:12; Jo 15:16)", "Responsabilidade – não basta ganhar vidas, é preciso apascentá-las (Jo 21:15-17)", "Obediência – a decisão de obedecer aos princípios e propósitos de Deus é individual (1Sm 15:22)"]}, {"titulo": "2.1 A Visão Celular atravessa três tipos de fronteiras", "itens": ["Geográficas – deixar o lugar de conforto e atravessar a rua, o bairro, a cidade, o país", "Linguísticas – o plano de Deus é que todos os povos ouçam o Evangelho em sua própria língua (At 2:8)", "Culturais – o Evangelho é imutável, mas sua apresentação deve ser adaptada: a embalagem muda, o remédio é o mesmo"]}, {"titulo": "3. Como fazer funcionar a Visão Celular", "texto": "É preciso entender os Princípios Bíblicos de Individualidade, União, Soberania e Mordomia. Os dons de cada um devem ser somados à liderança. Há três tipos de pessoas na Visão: as que sabem o que está acontecendo, as que observam e as que fazem as coisas acontecerem — todas devem ser envolvidas (1Co 12:21-22)."}, {"titulo": "Conclusão", "texto": "Ganhar... Consolidar... Discipular... Enviar. Esses princípios constituem a Visão Celular e declaram o alvo, a responsabilidade e a tarefa missionária da Igreja no mover celular."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 1, 'unica', $t$O que é a Visão Celular?$t$, $j${"opcoes": [{"id": "a", "texto": "Um programa feito apenas para pastores e missionários."}, {"id": "b", "texto": "Uma estratégia de crescimento e multiplicação do Reino de Jesus na Terra, nascida no coração de Deus, para fazer de cada membro do corpo de Cristo um discípulo líder."}, {"id": "c", "texto": "Uma reunião social para os membros se conhecerem."}, {"id": "d", "texto": "Um jeito de encher o templo sem precisar de discipulado."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Introdução da lição (Is 9:7; Jo 1:12).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 2, 'multipla', $t$Quais são os quatro princípios da Visão Celular? Marque os quatro.$t$, $j${"opcoes": [{"id": "a", "texto": "Ganhar"}, {"id": "b", "texto": "Competir"}, {"id": "c", "texto": "Consolidar"}, {"id": "d", "texto": "Discipular"}, {"id": "e", "texto": "Arrecadar"}, {"id": "f", "texto": "Enviar"}]}$j$::jsonb, $j$["a", "c", "d", "f"]$j$::jsonb, $t$Item 1: ganhar, consolidar, discipular e enviar.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 3, 'multipla', $t$Quais as implicações do IDE para a Igreja Celular?$t$, $j${"opcoes": [{"id": "a", "texto": "Privilégio"}, {"id": "b", "texto": "Comodidade"}, {"id": "c", "texto": "Responsabilidade"}, {"id": "d", "texto": "Popularidade"}, {"id": "e", "texto": "Obediência"}]}$j$::jsonb, $j$["a", "c", "e"]$j$::jsonb, $t$Item 2: privilégio (Jo 15:16), responsabilidade (Jo 21:15-17) e obediência (1Sm 15:22).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 4, 'multipla', $t$Quais os tipos de fronteiras que a Visão Celular atravessa?$t$, $j${"opcoes": [{"id": "a", "texto": "Geográficas"}, {"id": "b", "texto": "Financeiras"}, {"id": "c", "texto": "Linguísticas"}, {"id": "d", "texto": "Políticas"}, {"id": "e", "texto": "Culturais"}]}$j$::jsonb, $j$["a", "c", "e"]$j$::jsonb, $t$Item 2.1: fronteiras geográficas, linguísticas e culturais.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 5, 'unica', $t$Para que a Visão Celular?$t$, $j${"opcoes": [{"id": "a", "texto": "Para que cada igreja fique fechada em si mesma."}, {"id": "b", "texto": "Para que, juntos, possamos multiplicar discípulos para o Senhor Jesus não só em nossa nação, mas em todas as nações (etnias) da terra."}, {"id": "c", "texto": "Para substituir os cultos de celebração."}, {"id": "d", "texto": "Para ter mais reuniões durante a semana."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 2: Para que a Visão Celular?$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 6, 'lacunas', $t$Complete:$t$, $j${"partes": ["a) GANHAR é o princípio caracterizado pelo", null, "pessoal, maciço e/ou congregacional. b) CONSOLIDAR é caracterizado pela", null, "do fruto conquistado, através da atenção e dedicação. c) DISCIPULAR é caracterizado pelo", null, ". d) ENVIAR é caracterizado pelo", null, "de Jesus."]}$j$::jsonb, $j$[["evangelismo"], ["conservação", "conservacao"], ["ensino"], ["IDE"]]$j$::jsonb, $t$Itens 1.1 a 1.4: EVANGELISMO, CONSERVAÇÃO, ENSINO e IDE.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (11, 7, 'aberta', $t$Cite alguns propósitos do DISCIPULADO.$t$, $j${}$j$::jsonb, $j${"referencia": "Transmitir o Evangelho a discípulos fiéis (2Tm 3:14-15); levar à santidade (1Pe 1:13-25); batalhar pela fé (Jd 3); preparar para fortalecer outros na célula (Ef 4:11-16); experiência do Reino e batalha espiritual (Ef 6:10-18); batismo no Espírito, oração, jejum e adoração; dedicar-se à evangelização (Mt 28:18-20)."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (12, 2, 2, $t$Entendendo a importância do Ganhar$t$, $t$O que ganha almas é sábio.$t$, $t$Provérbios 11:30$t$, $j$[{"titulo": "Introdução", "texto": "A Visão Celular é o cumprimento da Grande Comissão dada por Jesus a todo aquele que O confessa como Senhor e Salvador: fazer discípulos (Mt 28:19-20). Para termos êxito, observamos os quatro princípios: ganhar, consolidar, discipular e enviar. Ganhar é o primeiro princípio e está relacionado a ganhar almas."}, {"titulo": "1.1 O que é alma?", "texto": "Alma é uma vida que, em todos os sentidos, precisa de Deus e da salvação de Cristo. Vem do grego psiquê: é a sede das emoções, da vontade, do desejo, da afeição, da mente, da razão e da compreensão — o “eu interior”, a pessoa em si."}, {"titulo": "1.2 O que é pregar?", "texto": "A palavra grega usada para “pregar” é Kerigma: anunciar, proclamar, publicar. Pelo IDE de Jesus, cada crente recebe um púlpito pessoal — em casa, na comunidade, no trabalho, na escola — para contar aos outros a boa notícia do Evangelho.", "ref": "Rm 10:13-15"}, {"titulo": "1.3 O que é o Evangelho?", "texto": "Evangelho vem do grego euaggelion e significa Boas Novas. São as boas notícias que Deus proveu: a salvação para os perdidos, através do nascimento, morte e ressurreição de Jesus Cristo (Jo 1:1; 3:16). Quando o Evangelho é pregado no poder do Espírito, há:", "itens": ["Autoridade de Cristo (Mt 28:18-20)", "Revelação da justiça de Deus (Rm 1:16-17)", "Arrependimento genuíno (Mt 3:2; 4:17)", "Convencimento do pecado, da justiça e do juízo (Jo 16:8)", "Salvação, vida e o dom do Espírito Santo (Rm 1:16)", "Libertação do domínio do pecado e de Satanás (Mt 12:28; At 26:18)", "Esperança, paz e imortalidade (Cl 1:5; Ef 2:17; 2Tm 1:10)", "Advertência sobre o juízo e a condenação quando rejeitado (Rm 2:16; Jo 3:18)"]}, {"titulo": "Qual a importância de ganhar almas?", "texto": "“Eu sou devedor” (Rm 1:14); “ai de mim se não pregar o evangelho” (1Co 9:16). Em Efésios 2, Paulo mostra por quê:", "itens": ["A pessoa sem Cristo está morta espiritualmente — precisa de vida (Ef 2:1)", "Está seguindo um caminho de destruição — precisa de libertação (Ef 2:2-3)", "Está sem esperança — precisa de Deus (Ef 2:12)", "Está separada de Deus — precisa de Jesus (Ef 2:13-14)"]}, {"titulo": "2. Os ganhadores de almas, segundo a Palavra", "itens": ["Mostram a mais alta sabedoria (Pv 11:30)", "Brilharão como as estrelas, sempre e eternamente (Dn 12:3)", "São treinados por Cristo numa nova chamada: “pescadores de homens” (Mt 4:19)", "Sacrificam direitos e privilégios pessoais (1Co 9:19)", "Arrebatam pessoas como tições tirados do fogo (Jd 23)"]}, {"titulo": "Conclusão", "texto": "O homem sem Deus está perdido, e somente através de Jesus Cristo pode ser redimido (Lc 19:10). Por isso o líder modelo se empenhará em cumprir os propósitos de Deus. Ganhar almas é imperativo: IDE e PREGAI o Evangelho da salvação."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (12, 1, 'multipla', $t$Qual a importância de ganhar almas? Segundo Efésios 2, a pessoa sem Cristo… (marque as corretas)$t$, $j${"opcoes": [{"id": "a", "texto": "Está morta espiritualmente e precisa de vida."}, {"id": "b", "texto": "Já está salva por ser uma boa pessoa."}, {"id": "c", "texto": "Segue um caminho de destruição e precisa de libertação."}, {"id": "d", "texto": "Está sem esperança e precisa de Deus."}, {"id": "e", "texto": "Não precisa que ninguém lhe fale de Jesus."}, {"id": "f", "texto": "Está separada de Deus e precisa de Jesus."}]}$j$::jsonb, $j$["a", "c", "d", "f"]$j$::jsonb, $t$Item 1.3: Ef 2:1-3, 2:12 e 2:13-14.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (12, 2, 'unica', $t$O que são as Boas Notícias (Boas Novas)?$t$, $j${"opcoes": [{"id": "a", "texto": "Notícias boas do jornal sobre a economia."}, {"id": "b", "texto": "As boas notícias que Deus proveu: a salvação para os perdidos, através do nascimento, morte e ressurreição de Jesus Cristo."}, {"id": "c", "texto": "Promessas de que nunca teremos problemas."}, {"id": "d", "texto": "As regras que a igreja exige dos membros."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 1.3 (Jo 3:16).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (12, 3, 'unica', $t$O que significa a palavra Evangelho?$t$, $j${"opcoes": [{"id": "a", "texto": "Vem do grego psiquê e significa “alma”."}, {"id": "b", "texto": "Vem do grego Kerigma e significa “anunciar”."}, {"id": "c", "texto": "Vem do grego euaggelion e significa Boas Novas."}, {"id": "d", "texto": "Significa “lei” ou “mandamento”."}]}$j$::jsonb, $j$"c"$j$::jsonb, $t$Item 1.3: euaggelion = Boas Novas. (Psiquê = alma; Kerigma = pregar, anunciar.)$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (12, 4, 'multipla', $t$Quais as qualificações de um ganhador de almas? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Faz a sua própria vontade"}, {"id": "b", "texto": "Mostra a mais alta sabedoria"}, {"id": "c", "texto": "Não se importa com os outros"}, {"id": "d", "texto": "Brilha"}, {"id": "e", "texto": "Sacrifica os direitos e os privilégios pessoais"}, {"id": "f", "texto": "Arrebata as pessoas como tições tirados do fogo"}, {"id": "g", "texto": "Cuida dos seus interesses pessoais"}]}$j$::jsonb, $j$["b", "d", "e", "f"]$j$::jsonb, $t$Item 2: Pv 11:30; Dn 12:3; 1Co 9:19; Jd 23.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (12, 5, 'aberta', $t$Descreva qual tem sido a sua estratégia para ganhar vidas.$t$, $j${}$j$::jsonb, $j${"referencia": "Resposta pessoal. Espera-se que o aluno descreva ações práticas de evangelismo (pessoal, na célula, no trabalho, na família) e o seu púlpito pessoal."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (13, 2, 3, $t$Lutando pelo Consolidar$t$, $t$Consolai, consolai o meu povo, diz o vosso Deus.$t$, $t$Isaías 40:1$t$, $j$[{"titulo": "Introdução", "texto": "É projeto de Deus que todo aquele que O recebe como Senhor e Salvador seja consolidado (Mt 11:28-29). Todos chegamos a Jesus quebrados e feridos, mas Ele nos recebe do jeito que estamos, consola e restaura. A consolidação é um processo contínuo: o discípulo é um filho espiritual, e devemos acompanhá-lo em todas as fases do seu crescimento."}, {"titulo": "1. O que é consolidação?", "texto": "Pode ser entendida de duas formas: como o processo da Visão, que leva o novo convertido do Pré-encontro à Escola de Líderes; e como um processo de vida, acompanhando os passos do novo convertido até que ele se torne maduro na fé. Consolidar é tornar sólido, estável, firme. É cuidar da ferida e da fratura do novo convertido, trazer consolo para a dor, a tristeza, a solidão e a falta de amor. Consolidar é servir, como Jesus (Mt 20:28). É um ato de amor: amar, investir, perseverar, perdoar e gerar filhos para Deus."}, {"titulo": "1.2 Três processos de consolidação de Deus para o homem", "itens": ["Deus consolidou o homem: ministrava a ele na viração do dia (Gn 2:16; 3:8)", "Deus não desiste do homem: “Eu vim para que tenham vida, e vida em abundância” (Jo 10:10)", "Deus estabeleceu aliança com o homem para resgatá-lo (Gn 3:15)"]}, {"titulo": "2. O que precisamos ter para consolidar?", "texto": "O ponto-chave, antes de qualquer estratégia, é amar vidas. Além disso:", "itens": ["ESTRUTURA – uma vida regida pelos Princípios Bíblicos: “Sede firmes e inabaláveis” (1Co 15:58)", "BASE – ser conhecedor da Palavra para ensinar a outros (2Tm 2:15)", "AMOR – fazer a obra sabendo que trabalhamos para Deus, e não para homens (Cl 3:23)"]}, {"titulo": "3. Para que devemos consolidar?", "texto": "Para que as pessoas sejam formadas em Jesus e na Sua Palavra, libertas das amarras do diabo, das feridas na alma, da rejeição e da incapacidade (Pv 23:7). Consolidar não é um processo mecânico: queremos discípulos capazes de tomar decisões acertadas, responsáveis, maduros e conscientes da sua missão."}, {"titulo": "4. Como consolidar no dia a dia da célula", "itens": ["Estabelecer os princípios para consolidar o caráter: dar bases bíblicas para que sejam firmados na nova fé (Rm 10:17)", "Gerar relacionamento para firmar alianças: o que consolida não é a estratégia, mas a CAMINHADA DIÁRIA", "Ganhar o discípulo num relacionamento de respeito e amizade, vivendo Jesus mais do que falando dEle", "Ser irrepreensível e transparente: “Sede meus imitadores, como também eu sou de Cristo” (1Co 11:1)", "Estar com os discípulos também em momentos informais, além de gabinetes, ministrações e orações"]}, {"titulo": "Conclusão", "texto": "O objetivo do consolidar vai muito além de uma classe para novos convertidos: é cuidar, ensinar e auxiliar quem começa a caminhada. É dever do discipulador suportar as fraquezas dos discípulos (Rm 15:1) e torná-los sólidos, estáveis e firmes na Palavra do Senhor."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (13, 1, 'unica', $t$O que é consolidação?$t$, $j${"opcoes": [{"id": "a", "texto": "Uma aula única dada no dia do batismo."}, {"id": "b", "texto": "Tornar sólido, estável e firme; cuidar da ferida e da fratura do novo convertido, acompanhando-o até que seja maduro na fé."}, {"id": "c", "texto": "Cobrar do novo convertido que mude sozinho."}, {"id": "d", "texto": "Apenas preencher a ficha do visitante."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 1: consolidar é tornar sólido, estável, firme (Is 40:1).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (13, 2, 'multipla', $t$O que precisamos ter para Consolidar? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Carro do ano"}, {"id": "b", "texto": "Estrutura"}, {"id": "c", "texto": "Dinheiro"}, {"id": "d", "texto": "Base"}, {"id": "e", "texto": "Carisma pessoal"}, {"id": "f", "texto": "Amor"}]}$j$::jsonb, $j$["b", "d", "f"]$j$::jsonb, $t$Item 2: Estrutura (1Co 15:58), Base (2Tm 2:15) e Amor (Cl 3:23).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (13, 3, 'multipla', $t$Quais são os três processos de consolidação de Deus para o homem?$t$, $j${"opcoes": [{"id": "a", "texto": "Deus consolidou o homem, ministrando a ele na viração do dia."}, {"id": "b", "texto": "Deus abandonou o homem depois da queda."}, {"id": "c", "texto": "Deus não desiste do homem."}, {"id": "d", "texto": "Deus estabeleceu aliança com o homem para resgatá-lo."}, {"id": "e", "texto": "Deus exige que o homem se consolide sozinho."}]}$j$::jsonb, $j$["a", "c", "d"]$j$::jsonb, $t$Item 1.2: Gn 2:16; 3:8 — Jo 10:10 — Gn 3:15.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (13, 4, 'aberta', $t$Pesquise na Bíblia e encontre textos que mostrem explicitamente uma consolidação sendo praticada.$t$, $j${}$j$::jsonb, $j${"referencia": "Exemplos: Barnabé acolhendo Saulo (At 9:26-27); Jesus restaurando Pedro (Jo 21:15-17); Paulo e Timóteo (1Tm 1:2; 2Tm 2:1-2); Paulo confirmando as igrejas (At 14:21-22); Jesus com a samaritana (Jo 4); Is 40:1."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (14, 2, 4, $t$Abraçando a Visão do Discipular$t$, $t$Portanto ide, fazei discípulos de todas as nações, batizando-os em nome do Pai, e do Filho, e do Espírito Santo; ensinando-os a guardar todas as coisas que vos tenho mandado.$t$, $t$Mateus 28:19-20$t$, $j$[{"titulo": "Introdução", "texto": "Depois de consolidado, o novo crente precisa aprofundar-se no conhecimento de Deus e da Sua graça. A melhor maneira é o discipulado: ensiná-lo com clareza os preceitos do Reino, para que prossiga para o alvo (Fp 3:14) e alcance a verdadeira vida (1Tm 6:19)."}, {"titulo": "1. Discipular", "texto": "Podemos definir discipular pelos termos hebraicos YARAH e LAMED:", "itens": ["YARAH – instruir, dirigir, ensinar, apontar, ativar, visar, arremessar, lançar em linha reta (Sl 32:8)", "LAMED – instruir, treinar, estimular, incitar, ensinar, fazer alguém aprender (Is 48:17)"]}, {"titulo": "2. Como se estabelece a visão do discipulador?", "texto": "No relacionamento do discipulador com o discípulo. Discipular nos dá responsabilidades especiais: não podemos negligenciar o cuidado dos discípulos, e devemos ser uma referência segura, refletindo claramente o caráter de Cristo."}, {"titulo": "3. Como se fundamenta?", "texto": "A orientação apostólica nas cartas à Igreja fundamenta a visão do discipular:", "itens": ["Equipando os discípulos e assistindo-os para uma vida e serviço frutíferos (Ef 4:11-12)", "Transmitindo a verdade a cada geração sucessiva de convertidos: “confia-o a homens fiéis, que sejam idôneos para também ensinarem os outros” (2Tm 2:2)"]}, {"titulo": "4. Princípios da visão do discipular", "texto": "São os princípios que perfilam o caráter do discipulador: SANTIDADE e FIDELIDADE, que geram o COMPROMISSO.", "itens": ["SANTIDADE (1Ts 3:13) – do grego hagiosune: o processo, a qualidade e a condição de uma disposição sagrada; santidade na conduta pessoal. A fonte da santidade é um relacionamento pessoal com Jesus, e não um sistema de obras.", "FIDELIDADE (Pv 25:13) – do termo fiel, no hebraico emunah: firmeza, estabilidade, lealdade, consciência, constância, segurança, aquilo que é permanente e duradouro.", "COMPROMISSO (At 26:19-20) – Paulo não foi desobediente à visão celestial: estava comprometido com o seu chamado."]}, {"titulo": "5. Aprendendo com o Mestre dos mestres, Jesus Cristo", "itens": ["As profecias messiânicas mostram o caráter servil de Jesus (Is 42; 49; 50; 53)", "Para abraçar a visão do discipular, precisamos aprender o espírito de Jesus como servo: Ele não veio para ser servido, mas para servir", "Cristo procura os que servem sem buscar reconhecimento", "Discipuladores e discípulos firmam o seu ministério na devoção e na obediência a Jesus"]}, {"titulo": "Conclusão", "texto": "Discipulado é o processo de uma vida. Ao assumirmos o treinamento de novos convertidos, tornamo-nos “pais espirituais” deles. Essa missão exige tempo, esforço, dedicação, renúncia e, sobretudo, muito amor a Deus e às vidas que chegam à Casa do Pai."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 1, 'unica', $t$Como se estabelece a visão do discipular?$t$, $j${"opcoes": [{"id": "a", "texto": "Pela quantidade de cursos que o discípulo fez."}, {"id": "b", "texto": "No relacionamento do discipulador com o discípulo."}, {"id": "c", "texto": "Apenas pela pregação no culto de domingo."}, {"id": "d", "texto": "Por meio de regras escritas."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 2.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 2, 'multipla', $t$Como se fundamenta o discipulado? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Equipando os discípulos e assistindo-os para uma vida e serviço frutíferos (Ef 4:11-12)."}, {"id": "b", "texto": "Deixando o discípulo aprender sozinho, sem acompanhamento."}, {"id": "c", "texto": "Transmitindo a verdade a cada geração de convertidos, para que também ensinem outros (2Tm 2:2)."}, {"id": "d", "texto": "Ensinando apenas quem já é líder."}]}$j$::jsonb, $j$["a", "c"]$j$::jsonb, $t$Item 3: Ef 4:11-12 e 2Tm 2:2.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 3, 'unica', $t$Qual o significado das palavras hebraicas YARAH e LAMED?$t$, $j${"opcoes": [{"id": "a", "texto": "YARAH: instruir, dirigir, ensinar, apontar, lançar em linha reta. LAMED: instruir, treinar, estimular, incitar, fazer alguém aprender."}, {"id": "b", "texto": "YARAH: alma. LAMED: boas novas."}, {"id": "c", "texto": "YARAH: santidade. LAMED: fidelidade."}, {"id": "d", "texto": "As duas significam “descansar”."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 1: Sl 32:8 e Is 48:17.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 4, 'multipla', $t$Quais os princípios que perfilam o caráter do discipulador?$t$, $j${"opcoes": [{"id": "a", "texto": "Santidade"}, {"id": "b", "texto": "Popularidade"}, {"id": "c", "texto": "Fidelidade"}, {"id": "d", "texto": "Riqueza"}]}$j$::jsonb, $j$["a", "c"]$j$::jsonb, $t$Item 4: Santidade e Fidelidade, que geram o Compromisso.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 5, 'unica', $t$Qual a origem das palavras SANTIDADE e FIDELIDADE?$t$, $j${"opcoes": [{"id": "a", "texto": "Santidade vem do hebraico emunah; Fidelidade vem do grego hagiosune."}, {"id": "b", "texto": "Santidade vem do grego hagiosune; Fidelidade vem do termo fiel, no hebraico emunah."}, {"id": "c", "texto": "As duas vêm do latim."}, {"id": "d", "texto": "Santidade vem de psiquê; Fidelidade vem de Kerigma."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Itens 4.1 e 4.2.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 6, 'unica', $t$Santidade e Fidelidade geram o quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Orgulho"}, {"id": "b", "texto": "Compromisso"}, {"id": "c", "texto": "Cansaço"}, {"id": "d", "texto": "Fama"}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 4: geram o COMPROMISSO (At 26:19-20).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 7, 'lacunas', $t$Complete:$t$, $j${"partes": ["A fonte da Santidade é um", null, "pessoal com Jesus e não um", null, "de obras."]}$j$::jsonb, $j$[["relacionamento"], ["sistema"]]$j$::jsonb, $t$Item 4.1: relacionamento pessoal com JESUS, e não um sistema de obras.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 8, 'unica', $t$Santidade, de origem da palavra grega hagiosune, significa o quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Ser melhor do que os outros."}, {"id": "b", "texto": "O processo, a qualidade e a condição de uma disposição sagrada e a qualidade de santidade na conduta pessoal."}, {"id": "c", "texto": "Cumprir rituais religiosos."}, {"id": "d", "texto": "Afastar-se de todas as pessoas."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 4.1 (1Ts 3:13).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 9, 'unica', $t$Fidelidade, palavra derivada do termo fiel, que no hebraico é emunah, significa o quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Firmeza, estabilidade, lealdade, consciência, constância, segurança; aquilo que é permanente e duradouro."}, {"id": "b", "texto": "Alegria passageira."}, {"id": "c", "texto": "Riqueza e prosperidade."}, {"id": "d", "texto": "Rapidez para mudar de ideia."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 4.2 (Pv 25:13).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 10, 'unica', $t$O termo usado para guardador no hebraico é shamar e significa:$t$, $j${"opcoes": [{"id": "a", "texto": "Esquecer, abandonar."}, {"id": "b", "texto": "Guardar, vigiar, proteger, cuidar com atenção."}, {"id": "c", "texto": "Correr, apressar-se."}, {"id": "d", "texto": "Vender, negociar."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Shamar: guardar, vigiar, proteger e observar com cuidado — o discipulador guarda os seus discípulos.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 11, 'aberta', $t$Qual o perfil de um discipulador de êxito?$t$, $j${}$j$::jsonb, $j${"referencia": "Vive em santidade e fidelidade e tem compromisso com o chamado; relaciona-se de perto com o discípulo e é referência segura do caráter de Cristo; tem espírito de servo como Jesus; ensina, treina e estimula; age como pai espiritual, com tempo, dedicação, renúncia e amor."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (14, 12, 'aberta', $t$O que você precisa para melhorar o seu discipulado?$t$, $j${}$j$::jsonb, $j${"referencia": "Resposta pessoal."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (15, 2, 5, $t$Preparando-se para Enviar$t$, $t$Ide, portanto, fazei discípulos de todas as nações, batizando-os em nome do Pai, do Filho e do Espírito Santo; ensinando-os a guardar todas as coisas que vos tenho ordenado.$t$, $t$Mateus 28:19-20$t$, $j$[{"titulo": "Introdução", "texto": "Não podemos falar de enviar alguém sem compreender todo o processo: ganhar, consolidar e treinar, para então enviar. O que gera um líder pronto para ser enviado é o processo, e não o comissionamento. Não basta escolher uma pessoa cheia de qualidades e enviá-la a uma missão para a qual não está pronta."}, {"titulo": "1. Entendendo os passos da Visão", "texto": "O enviar é consequência de todo o processo da Visão. Os passos formam uma unidade funcional: um não funciona sem o outro."}, {"titulo": "1.1 Ninguém é enviado sem que primeiro seja ganho", "texto": "Ganhamos vidas já pensando em prepará-las para o seu papel profético-sacerdotal: anunciar o Evangelho. Não ganhamos pessoas para uma estatística. Deus nos amou; por isso amamos as pessoas, com paciência no processo de cada uma, ganhando-as pelo testemunho pessoal e despertando nelas o desejo de serem como Jesus (Jo 14:6)."}, {"titulo": "1.2 Somente alguém consolidado suporta o treinamento", "texto": "A consolidação (Fp 4:10-13) é, primeiro, parte da metodologia da Visão: levar o novo convertido do pré-encontro ao pós-encontro e matriculá-lo na Escola de Líderes. Segundo, é o acompanhamento pessoal até a maturidade cristã. Trabalhamos para gerar filhos espirituais que saibam agir com autonomia, responsabilidade, respeito, santidade e temor a Deus."}, {"titulo": "1.3 Recebendo treinamento para prosperar na Visão", "texto": "Treinar é municiar: dar ao soldado as armas com as quais poderá lutar sem ser destruído e ensiná-lo a usá-las. Na batalha espiritual, nossas armas não são carnais, mas espirituais em Cristo Jesus."}, {"titulo": "2. O que é preciso para ser enviado?", "itens": ["HUMILDADE – reconhecer que precisamos de libertação e cura, como Isaías: “Ai de mim!” — e depois responder: “Eis-me aqui” (Is 6)", "HONESTIDADE – portar-se com transparência diante dos homens, pois diante de Deus nada pode ser escondido", "RENÚNCIA – renunciar à velha natureza: Moisés tirou as sandálias (Êx 3:5) para calçar as sandálias do evangelho da paz (Ef 6:15)"]}, {"titulo": "Conclusão", "texto": "Precisamos estabelecer uma base sólida para que o enviar produza efeito. A Palavra de Deus nos mostra vários exemplos de envio com sucesso; seguindo esses princípios com cuidado, teremos êxito na tarefa."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (15, 1, 'unica', $t$Por que ninguém é enviado sem que primeiro seja ganho?$t$, $j${"opcoes": [{"id": "a", "texto": "Porque o enviar é consequência de todo o processo da Visão: ganhamos as vidas já para prepará-las para o seu papel de anunciadoras do Evangelho."}, {"id": "b", "texto": "Porque é preciso ter muitos membros para fazer estatística."}, {"id": "c", "texto": "Porque só pastores podem ser enviados."}, {"id": "d", "texto": "Não é necessário ser ganho para ser enviado."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Itens 1 e 1.1.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (15, 2, 'unica', $t$Como podemos suportar o treinamento?$t$, $j${"opcoes": [{"id": "a", "texto": "Com força de vontade própria, sem ajuda."}, {"id": "b", "texto": "Sendo consolidados: levados do pré-encontro ao pós-encontro e à Escola de Líderes, e acompanhados até a maturidade cristã."}, {"id": "c", "texto": "Faltando às aulas mais difíceis."}, {"id": "d", "texto": "Pulando direto para o envio."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 1.2: somente alguém consolidado suporta o treinamento (Fp 4:10-13).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (15, 3, 'unica', $t$Como prosperar na Visão?$t$, $j${"opcoes": [{"id": "a", "texto": "Recebendo treinamento: sendo municiado com armas espirituais e aprendendo a usá-las."}, {"id": "b", "texto": "Usando armas carnais nas batalhas."}, {"id": "c", "texto": "Trabalhando sozinho, sem líder."}, {"id": "d", "texto": "Esperando que tudo aconteça sem preparo."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 1.3.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (15, 4, 'multipla', $t$O que é preciso para ser enviado? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Humildade"}, {"id": "b", "texto": "Fama"}, {"id": "c", "texto": "Honestidade"}, {"id": "d", "texto": "Dinheiro"}, {"id": "e", "texto": "Renúncia"}]}$j$::jsonb, $j$["a", "c", "e"]$j$::jsonb, $t$Item 2: Humildade (Is 6), Honestidade e Renúncia (Êx 3:5; Ef 6:15).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (16, 2, 6, $t$Como liderar uma Célula$t$, $t$E perseveravam na doutrina dos apóstolos, e na comunhão, e no partir do pão, e nas orações... E acrescentava o Senhor à igreja aqueles que se haviam de salvar.$t$, $t$Atos 2:42-47$t$, $j$[{"titulo": "Introdução", "texto": "Deus nos chamou para o êxito no Seu propósito. Temos um compromisso profético-sacerdotal, mas não basta ter consciência disso: é preciso preparar-se. Ser líder de uma célula exige consciência e preparação."}, {"titulo": "1 e 2. O caráter do líder de células", "texto": "Antes de liderar outros, o líder precisa ser liderado, cultivando as características de uma pessoa segundo o coração de Deus. Todo liderado gosta de seguir um líder que sabe para onde está indo (Mt 4:19). O dever do líder é consolidar o discípulo no espírito, na alma e no corpo, e ensiná-lo a pescar outras vidas para o Reino de Deus."}, {"titulo": "3. A influência do líder de célula", "texto": "As pessoas são influenciadas primeiro pelo que veem. Ser modelo influencia muitos, mas o impacto mais profundo acontece de perto, trabalhando com as pessoas individualmente. O mais alto nível de influência é a multiplicação, que exige desprendimento do ego, generosidade, compromisso e tempo."}, {"titulo": "4. Estrutura de uma célula", "texto": "O lugar mais recomendado para a célula é, preferencialmente, uma casa — que pode ser a do próprio líder — com o mínimo de conforto. O líder deve deixar o lugar arrumado e limpo, orar e ungir o ambiente, chegar com antecedência e zelar pelo bem-estar do anfitrião."}, {"titulo": "5. Célula: ponto de encontro com Deus", "texto": "A cada semana, liderados e visitantes renovam e recordam tudo o que os levará a serem líderes de êxito. Fatores indispensáveis:", "itens": ["Fixar dia e horário da reunião e não mudar sem aviso prévio", "Reunir num lugar nobre: a sua casa ou a de alguém realmente comprometido — jamais no templo (igreja é lugar de celebração)", "Saber a diferença entre reunião de M12 e célula", "Assentos adequados; local coberto (sol e chuva); banheiro em ordem; água potável", "Conforto térmico, pouco barulho, boa iluminação e aparelho de som"]}, {"titulo": "6. A programação de uma célula", "texto": "Mínimo de 1 hora e máximo de 1 hora e meia, com pontualidade no início e no fim:", "itens": ["Introdução – 5 minutos: boas-vindas", "Louvor e adoração – 10 minutos", "Ministração do estudo para as células – 30 minutos", "Consolidação de novos discípulos – 5 minutos: oração de aplicação e oração de entrega", "Oferta – 5 minutos: ensinar a ofertar com propósito", "Avisos e oração final – 5 minutos", "Confraternização e comunhão: o partir do pão (At 2:42; Lc 6:38)"]}, {"titulo": "Conclusão", "texto": "A célula é o lugar de ganharmos pessoas para o Reino de Deus, com estratégia, unção e, principalmente, amor. Tudo se resume em: amor pelos liderados e paixão por vidas."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 1, 'unica', $t$Qual o dever do líder de célula?$t$, $j${"opcoes": [{"id": "a", "texto": "Apenas abrir a casa para a reunião."}, {"id": "b", "texto": "Consolidar o discípulo no espírito, na alma e no corpo, e ensiná-lo a pescar outras vidas para o Reino de Deus."}, {"id": "c", "texto": "Controlar a vida dos liderados."}, {"id": "d", "texto": "Pregar somente nos cultos da igreja."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 2: o caráter do líder de células.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 2, 'multipla', $t$Quais aspectos importantes devem fazer parte da estrutura de uma célula? Marque os corretos.$t$, $j${"opcoes": [{"id": "a", "texto": "Reunir, preferencialmente, em uma casa com o mínimo de conforto."}, {"id": "b", "texto": "Deixar o lugar arrumado e limpo antes da chegada das pessoas."}, {"id": "c", "texto": "Orar e ungir o ambiente."}, {"id": "d", "texto": "Reunir no templo, na hora do culto."}, {"id": "e", "texto": "Chegar com antecedência e zelar pelo bem-estar do anfitrião."}, {"id": "f", "texto": "Não se preocupar com o local."}]}$j$::jsonb, $j$["a", "b", "c", "e"]$j$::jsonb, $t$Item 4: estrutura de uma célula.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 3, 'aberta', $t$Explique a afirmação: “A reunião celular é o ponto de encontro com Deus”.$t$, $j${}$j$::jsonb, $j${"referencia": "A cada semana, liderados e visitantes têm um momento de renovar e recordar o que os levará a serem líderes de êxito e de aprender as verdades divinas; é um ambiente preparado, ungido e cheio da presença de Deus (item 5)."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 4, 'multipla', $t$Marque os procedimentos que antecedem uma boa reunião de célula (a lição cita vários).$t$, $j${"opcoes": [{"id": "a", "texto": "Fixar dia e horário da reunião."}, {"id": "b", "texto": "Mudar o horário toda semana sem avisar."}, {"id": "c", "texto": "Reunir em lugar nobre: a casa do líder ou de alguém comprometido."}, {"id": "d", "texto": "Ter assentos adequados e local coberto."}, {"id": "e", "texto": "Banheiro em ordem e água potável disponível."}, {"id": "f", "texto": "Reunir no templo durante o culto."}, {"id": "g", "texto": "Ambiente com pouco barulho, boa luz e aparelho de som."}]}$j$::jsonb, $j$["a", "c", "d", "e", "g"]$j$::jsonb, $t$Item 5: fatores indispensáveis para a reunião celular.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 5, 'aberta', $t$Explique por que a casa do líder é o melhor lugar para reunir uma célula.$t$, $j${}$j$::jsonb, $j${"referencia": "A casa é lugar nobre e acolhedor; o líder pode prepará-la (arrumar, limpar, orar e ungir o ambiente), garantir conforto aos liderados e visitantes e mostrar a sua vida como modelo; igreja (templo) é lugar de celebração (itens 4 e 5)."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 6, 'lacunas', $t$Qual o tempo mínimo de duração de uma célula e como ele está distribuído? Complete:$t$, $j${"partes": ["A célula deve durar no mínimo", null, "hora (e no máximo 1 hora e meia). Introdução:", null, "minutos. Louvor e adoração:", null, "minutos. Ministração do estudo:", null, "minutos. Consolidação, oferta e avisos/oração final: 5 minutos cada."]}$j$::jsonb, $j$[["1", "uma"], ["5", "cinco"], ["10", "dez"], ["30", "trinta"]]$j$::jsonb, $t$Item 6 e 6.1: distribuição do tempo na célula.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (16, 7, 'aberta', $t$Explique, com suas palavras, a importância de cada passo da célula, desde a introdução até a oração final.$t$, $j${}$j$::jsonb, $j${"referencia": "Introdução: deixar todos à vontade; Louvor: preparar o coração e abrir o entendimento; Ministração: ensinar a Palavra (estudo do pastor); Consolidação: aplicar o estudo e oração de entrega; Oferta: ensinar a ofertar com propósito; Avisos e oração final: manter informados, ligar a célula à igreja e abençoar."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (17, 2, 7, $t$Compreendendo a Visão: o Modelo dos 12$t$, $t$E, chamando a si os seus doze discípulos, deu-lhes autoridade sobre os espíritos imundos, para expulsarem, e para curarem toda sorte de doenças e enfermidades.$t$, $t$Mateus 10:1$t$, $j$[{"titulo": "Introdução", "texto": "O amor consolida uma vida, ajuda a organizá-la e restaurá-la. Deus é amor (1Jo 4:16); por isso o primeiro consolidador do homem é Deus. Na Visão Celular, ganhamos vidas pelo amor que Ele derramou em nossos corações (Rm 5:5)."}, {"titulo": "1. Por que células? (Modelo dos 12)", "texto": "Não é um ajuntamento de grupo, mas a formação de uma equipe de discípulos — como Jesus fez com os Seus doze — que trabalhará com perspectiva de conquista, visando alcançar as multidões. O grupo celular é a chave para a multiplicação: só um grupo organizado e unido conquista territórios."}, {"titulo": "2. A importância do modelo", "texto": "Fazer parte do Modelo e estar na Visão Celular é um privilégio. Ser modelo é ser um líder libertador, que sabe administrar e que aprendeu a trabalhar em equipe."}, {"titulo": "3. Gerando uma liderança modelo", "texto": "Gerar um líder é conquistar um território. Tudo o que falamos tem grande peso na vida do discípulo: podemos atraí-lo ou afastá-lo. Só um líder de êxito, com frutos, caráter irrepreensível e bom testemunho, conquista esse território. A equipe deve encontrar no líder modelo: a referência, o respaldo e um estilo de vida a ser seguido. Qualificações:", "itens": ["SABEDORIA – sábio para o bem e simples para o mal; sabedoria no falar, no agir e no julgar os problemas", "ENTENDIMENTO – a obediência faz o discípulo ter um só coração com o líder", "FORMAÇÃO – ser referência de obediência como Jesus: “a fôrma que forma”", "COBERTURA – é a proteção, a segurança; estar debaixo de cobertura é estar na bênção do Senhor (Tg 1:17)", "CORREÇÃO EM AMOR – corrigir não é punir, é instruir no caminho certo, sem dureza (Sl 119:176)", "ORIENTAÇÃO – mostrar o caminho; os discípulos não são descartáveis, precisam ser orientados pela Palavra"]}, {"titulo": "Conclusão", "texto": "Somos “a fôrma que forma” e não podemos recuar. Se formos fiéis à Visão, essa fidelidade forjará em nós o caráter de verdadeiros guerreiros. Onde há fidelidade, há conquista, sempre!"}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (17, 1, 'aberta', $t$Com suas próprias palavras, descreva o que é o Modelo dos 12.$t$, $j${}$j$::jsonb, $j${"referencia": "Não é um simples grupo, mas a formação de uma equipe de doze discípulos (como Jesus fez), treinados e organizados para ganhar, consolidar, discipular e enviar, multiplicando-se em gerações e conquistando as multidões."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (17, 2, 'unica', $t$Qual a importância do Modelo dos 12?$t$, $j${"opcoes": [{"id": "a", "texto": "Nenhuma: é só uma forma de organizar listas."}, {"id": "b", "texto": "É a chave para a multiplicação: forma uma equipe de discípulos organizada e unida para conquistar; ser modelo é ser um líder libertador que sabe administrar e trabalhar em equipe."}, {"id": "c", "texto": "Serve para escolher os mais importantes da igreja."}, {"id": "d", "texto": "Serve para diminuir o número de células."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Itens 1 e 2.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (17, 3, 'multipla', $t$Que qualificações são necessárias a um líder da Visão Celular no Modelo dos 12? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Sabedoria"}, {"id": "b", "texto": "Autoritarismo"}, {"id": "c", "texto": "Entendimento"}, {"id": "d", "texto": "Formação"}, {"id": "e", "texto": "Vaidade"}, {"id": "f", "texto": "Cobertura"}, {"id": "g", "texto": "Correção em amor"}, {"id": "h", "texto": "Orientação"}]}$j$::jsonb, $j$["a", "c", "d", "f", "g", "h"]$j$::jsonb, $t$Item 3: sabedoria, entendimento, formação, cobertura, correção em amor e orientação.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (17, 4, 'aberta', $t$Pesquise na Bíblia os nomes dos 12: a) filhos de Israel; b) valentes de Davi; c) discípulos de Jesus.$t$, $j${}$j$::jsonb, $j${"referencia": "a) Gn 35:23-26 — Rúben, Simeão, Levi, Judá, Issacar, Zebulom, José, Benjamim, Dã, Naftali, Gade e Aser. b) 1Cr 27:1-15 (os doze chefes do exército de Davi) — Jasobeão, Dodai, Benaia, Asael, Samute, Ira, Helez, Sibecai, Abiezer, Maarai, Benaia (o piratonita) e Heldai. c) Mt 10:2-4 — Pedro, André, Tiago, João, Filipe, Bartolomeu, Tomé, Mateus, Tiago (filho de Alfeu), Tadeu, Simão e Judas Iscariotes."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (17, 5, 'unica', $t$O que é cobertura?$t$, $j${"opcoes": [{"id": "a", "texto": "Um teto para a reunião da célula."}, {"id": "b", "texto": "É a proteção, a segurança: estar debaixo de cobertura é estar na bênção do Senhor; o líder dá aos discípulos o que recebe de Deus e os protege."}, {"id": "c", "texto": "É esconder os erros dos discípulos."}, {"id": "d", "texto": "É mandar nos discípulos sem prestar contas a ninguém."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 3.4 (Tg 1:17).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (18, 2, 8, $t$Como formar uma Equipe Modelo$t$, $t$Portanto, nós também, pois estamos rodeados de uma tão grande nuvem de testemunhas, deixemos todo embaraço, e o pecado que tão de perto nos rodeia, e corramos com perseverança a carreira que nos está proposta.$t$, $t$Hebreus 12:1$t$, $j$[{"titulo": "Introdução", "texto": "Jesus, ao escolher os Seus 12, investiu profundamente na formação da Sua equipe. O impacto seria proporcional ao caráter, às habilidades e ao relacionamento dos seus componentes. Equipar os santos é o alicerce para que o Corpo de Cristo funcione bem (Ef 4:11-16)."}, {"titulo": "1. O que é uma equipe", "texto": "Um conjunto de pessoas comprometidas, capacitadas e coordenadas para obter os mesmos alvos, sonhos e metas."}, {"titulo": "2. Como formar uma equipe modelo: começando pela liderança", "texto": "A liderança deve ser clara, forte e madura, com direção segura e prioridades definidas, ajudando a equipe a desenvolver dons e talentos. O líder precisa da sabedoria de Deus para lidar com as diferenças e deve inspirar pelo próprio exemplo: a equipe decola tanto quanto o seu líder."}, {"titulo": "3. Os membros da equipe", "texto": "Devem ser observados pela sua maturidade, em dois aspectos:", "itens": ["Habilidade ou competência no trabalho: conhecimento, experiência e dons espirituais", "Motivação ou compromisso: caráter, chamado, vontade, desejo, confiança e relacionamento com o líder"]}, {"titulo": "4. Características de uma equipe", "itens": ["Depender de Deus — Palavra e oração (Jo 5:19-20; At 6:4)", "Ser consagrada a Deus — a consagração pessoal de cada membro dá liberdade para Deus agir (Lv 11:44)", "Ter unção (1Jo 2:20)", "Possuir um propósito em comum (Am 3:3)", "Ter união e compromisso com os alvos da equipe (Ec 4:9-12)", "Ter clareza quanto ao papel de cada membro (Ef 4:11-12)", "Experimentar a graça e o poder dos dons espirituais", "Identificar o papel de cada um pelos seus talentos e personalidade", "Mostrar eficiência nas reuniões", "Ter boa amizade e relacionamentos saudáveis (Fp 2:1-5)", "Amar incondicionalmente", "Alicerçar os membros na Palavra de Deus (2Tm 3:16)", "Reconhecer a graça de Deus no líder e atender à sua voz (Hb 13:17)"]}, {"titulo": "Talento e personalidade", "texto": "Talento é um padrão de pensamento, sentimento ou comportamento que se repete naturalmente; pode ser identificado pelos anseios do coração, pela aprendizagem rápida, pelo prazer e pelas reações espontâneas. A personalidade define a motivação: a forma como cada membro enxerga a responsabilidade de cumprir uma tarefa. Há pessoas estruturadas e não estruturadas, motivadas por tarefas ou por pessoas — e todas precisam umas das outras."}, {"titulo": "Reuniões e relacionamentos", "texto": "Dois ingredientes básicos para uma equipe ser eficiente: maturidade na prestação de contas e rendimentos (líder + membros); e sabedoria do líder para saber quando um assunto deve ser discutido, quando a equipe deve ser consultada e quando deve ser apenas informada. Quando a equipe não compartilha as mesmas expectativas, surgem frustrações, conflitos, desânimos e mal-entendidos."}, {"titulo": "Alicerçados na Palavra", "texto": "Toda equipe precisa ter uma base bíblica e ser orientada por princípios e valores bíblicos, para que os frutos permaneçam.", "ref": "2Tm 3:16"}, {"titulo": "Conclusão", "texto": "Como equipe, juntos fazemos para o Reino algo que nenhum de nós conseguiria fazer sozinho (Hb 12:1). A equipe é a base para realizarmos os projetos de Deus com sucesso."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 1, 'unica', $t$O que é uma equipe?$t$, $j${"opcoes": [{"id": "a", "texto": "Um grupo de pessoas que se encontra por acaso."}, {"id": "b", "texto": "Um conjunto de pessoas comprometidas, capacitadas e coordenadas para obter os mesmos alvos, sonhos e metas."}, {"id": "c", "texto": "Pessoas que trabalham cada uma do seu jeito, sem líder."}, {"id": "d", "texto": "Um grupo de amigos que só se reúne para festas."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 1.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 2, 'unica', $t$Como formar uma equipe modelo?$t$, $j${"opcoes": [{"id": "a", "texto": "Começando pela liderança: um líder claro, forte e maduro, com direção segura, que inspira pelo próprio exemplo e desenvolve os dons da equipe."}, {"id": "b", "texto": "Escolhendo só as pessoas mais ricas."}, {"id": "c", "texto": "Exigindo resultados sem dar o exemplo."}, {"id": "d", "texto": "Deixando cada um fazer o que quiser."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 2.1.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 3, 'multipla', $t$Os membros de uma equipe devem ser observados pela sua maturidade, que deve obedecer a dois aspectos. Quais?$t$, $j${"opcoes": [{"id": "a", "texto": "Habilidade ou competência no trabalho a ser feito"}, {"id": "b", "texto": "Aparência física"}, {"id": "c", "texto": "Motivação ou compromisso"}, {"id": "d", "texto": "Idade"}]}$j$::jsonb, $j$["a", "c"]$j$::jsonb, $t$Item 3.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 4, 'multipla', $t$Quais as características de uma equipe? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Depender de Deus"}, {"id": "b", "texto": "Ser consagrada a Deus"}, {"id": "c", "texto": "Ter unção"}, {"id": "d", "texto": "Individualismo"}, {"id": "e", "texto": "Possuir um propósito em comum"}, {"id": "f", "texto": "Ter união e compromisso com os alvos"}, {"id": "g", "texto": "Competição entre os membros"}, {"id": "h", "texto": "Amar incondicionalmente"}, {"id": "i", "texto": "Alicerçar-se na Palavra de Deus"}]}$j$::jsonb, $j$["a", "b", "c", "e", "f", "h", "i"]$j$::jsonb, $t$Item 4: características de uma equipe.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 5, 'multipla', $t$Quais os ingredientes básicos para uma equipe ser eficiente?$t$, $j${"opcoes": [{"id": "a", "texto": "Maturidade na prestação de contas e rendimentos (líder + membros)."}, {"id": "b", "texto": "Fazer reuniões longas e sem pauta."}, {"id": "c", "texto": "Sabedoria do líder para saber quando discutir, quando consultar e quando apenas informar a equipe."}, {"id": "d", "texto": "Decidir tudo por votação."}]}$j$::jsonb, $j$["a", "c"]$j$::jsonb, $t$Item 4, letra i: eficiência nas reuniões.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 6, 'multipla', $t$Quando uma equipe não compartilha as mesmas expectativas, pode gerar o quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Frustrações"}, {"id": "b", "texto": "Conflitos"}, {"id": "c", "texto": "Crescimento garantido"}, {"id": "d", "texto": "Desânimos"}, {"id": "e", "texto": "Mal-entendidos"}]}$j$::jsonb, $j$["a", "b", "d", "e"]$j$::jsonb, $t$Item 4, letra j.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 7, 'unica', $t$Para que Deus aja em cada membro da equipe é necessário o quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Que cada membro tenha muito dinheiro."}, {"id": "b", "texto": "A consagração pessoal de cada membro, separando-se do mal (Lv 11:44)."}, {"id": "c", "texto": "Que todos tenham a mesma personalidade."}, {"id": "d", "texto": "Nada: Deus age de qualquer forma."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 4, letra b.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 8, 'multipla', $t$O talento pode ser identificado através do quê?$t$, $j${"opcoes": [{"id": "a", "texto": "Anseios do coração"}, {"id": "b", "texto": "Aprendizagem rápida"}, {"id": "c", "texto": "Sorteio"}, {"id": "d", "texto": "Prazer em fazer"}, {"id": "e", "texto": "Reações espontâneas"}, {"id": "f", "texto": "Opinião de estranhos"}]}$j$::jsonb, $j$["a", "b", "d", "e"]$j$::jsonb, $t$Item 4, letra h.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 9, 'unica', $t$O que é personalidade?$t$, $j${"opcoes": [{"id": "a", "texto": "É o que define a motivação: a forma como cada membro enxerga a responsabilidade de cumprir uma tarefa."}, {"id": "b", "texto": "É a aparência da pessoa."}, {"id": "c", "texto": "É o cargo que a pessoa ocupa."}, {"id": "d", "texto": "É a mesma coisa que talento."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 4, letra h.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (18, 10, 'lacunas', $t$Preencha as lacunas:$t$, $j${"partes": ["Toda equipe precisa ter uma base", null, "e ser orientada por", null, "e valores bíblicos."]}$j$::jsonb, $j$[["bíblica", "biblica"], ["princípios", "principios"]]$j$::jsonb, $t$Item 4, letra m (2Tm 3:16).$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_aulas(id, modulo, numero, titulo, versiculo, versiculo_ref, conteudo) values (19, 2, 9, $t$A multiplicação pelas Equipes Modelo$t$, $t$E, perseverando unânimes todos os dias no templo, e partindo o pão em casa, comiam juntos com alegria e singeleza de coração, louvando a Deus, e caindo na graça de todo o povo. E todos os dias acrescentava o Senhor à igreja aqueles que se haviam de salvar.$t$, $t$Atos 2:46-47$t$, $j$[{"titulo": "Introdução", "texto": "Temos o desafio de encontrar um modelo de multiplicação sadio, duradouro e segundo o coração de Deus. Conviver com as diferenças entre os que têm o mesmo nível de autoridade e, disso, gerar multiplicação é tarefa de todos nós. Para ter êxito como equipe, precisamos pensar de uma só forma e em uma só coisa."}, {"titulo": "1. O que é equipe", "texto": "Equipe é um conjunto de pessoas que, juntas, interagem plenamente entre si e trabalham unânimes rumo a um mesmo e único objetivo. Para que a equipe tenha êxito, é necessário:", "itens": ["Haver interação (sinergia) — quando o povo andava unido, vencia (At 2:46)", "Haver unidade em meio à diversidade (Rm 12:5-8) — temos diferentes níveis de unção, mas o mesmo lugar no coração do Pai; cada um deve encontrar o seu lugar em Deus, acabando com facções e carnalidades", "Focalizar objetivos comuns — o que nos torna um não são as nossas habilidades, mas as nossas convicções comuns"]}, {"titulo": "2. O que é multiplicação", "texto": "É o resultado do trabalho da equipe rumo ao alvo da Visão: ganhar vidas. Não basta ter bons talentos: a equipe precisa trabalhar de forma organizada. Para uma multiplicação de êxito:", "itens": ["Cumprir uma VISÃO (sonho) definida e clara — clara para o líder e no coração e na mente da equipe", "Cumprir uma MISSÃO (a estratégia da visão) definida e clara — para o líder e para a equipe", "Os doze trabalharem em unidade: sem atitude coletiva, não há conquista coletiva"]}, {"titulo": "2.4 Um exemplo de multiplicação", "texto": "Sugestão: depois de jejum e oração, ministre à equipe a meta que Deus colocou no seu coração; proclame-a de forma visível (cartazes, estandartes); envolva cada líder na responsabilidade; diga não só o que fazer, mas como fazer; e organize um calendário de atividades de janeiro a dezembro para cumprir a meta."}, {"titulo": "Conclusão", "texto": "Uma multiplicação modelo precisa de uma equipe modelo, que interaja, seja uma mesmo em meio às diferenças e tenha um alvo comum, com visão e missão claras no coração do líder e da equipe. Não multiplicamos de qualquer forma: olhamos para Jesus, o discipulador maior."}]$j$::jsonb) on conflict (id) do update set modulo=excluded.modulo, numero=excluded.numero, titulo=excluded.titulo, versiculo=excluded.versiculo, versiculo_ref=excluded.versiculo_ref, conteudo=excluded.conteudo;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 1, 'unica', $t$Com suas palavras, explique o que é equipe. Qual alternativa resume a definição da lição?$t$, $j${"opcoes": [{"id": "a", "texto": "Um conjunto de pessoas que, juntas, interagem plenamente entre si e trabalham unânimes rumo a um mesmo e único objetivo."}, {"id": "b", "texto": "Pessoas que competem entre si por posição."}, {"id": "c", "texto": "Um grupo em que só o líder trabalha."}, {"id": "d", "texto": "Pessoas que se reúnem sem objetivo definido."}]}$j$::jsonb, $j$"a"$j$::jsonb, $t$Item 1.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 2, 'multipla', $t$O que é necessário para termos uma equipe de êxito? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Haver interação"}, {"id": "b", "texto": "Cada um trabalhar sozinho"}, {"id": "c", "texto": "Haver unidade"}, {"id": "d", "texto": "Focalizar objetivos comuns"}, {"id": "e", "texto": "Disputar tarefas mais importantes"}]}$j$::jsonb, $j$["a", "c", "d"]$j$::jsonb, $t$Itens 1.1, 1.2 e 1.3.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 3, 'aberta', $t$Explique o que é ter unidade em meio às diferenças.$t$, $j${}$j$::jsonb, $j${"referencia": "Conviver com as diferenças (de dons, unção, personalidade) entre os que têm o mesmo nível de autoridade, sabendo que todos têm o mesmo lugar no coração do Pai e que cada um tem o seu lugar em Deus; acabar com facções, ciúmes e carnalidades e trabalhar pelo mesmo objetivo (Rm 12:5-8)."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 4, 'unica', $t$Qual a importância de focarmos objetivos comuns em uma equipe?$t$, $j${"opcoes": [{"id": "a", "texto": "Nenhuma: cada um deve ter o seu próprio objetivo."}, {"id": "b", "texto": "O que nos torna um não são nossas habilidades, mas nossas convicções comuns; mesmo agindo de formas diferentes, trabalhamos pelo mesmo alvo e a multiplicação é eficaz."}, {"id": "c", "texto": "Serve apenas para evitar reuniões."}, {"id": "d", "texto": "Faz todos pensarem e agirem exatamente igual em tudo."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 1.3.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 5, 'unica', $t$O que é multiplicação?$t$, $j${"opcoes": [{"id": "a", "texto": "Aumentar o número de pessoas de qualquer forma."}, {"id": "b", "texto": "O resultado do trabalho organizado da equipe rumo ao alvo de ganhar vidas, em que cada discípulo conquistado reflete o caráter de Cristo."}, {"id": "c", "texto": "Dividir a célula quando há brigas."}, {"id": "d", "texto": "Fazer mais reuniões por semana."}]}$j$::jsonb, $j$"b"$j$::jsonb, $t$Item 2.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 6, 'multipla', $t$Como podemos ter uma multiplicação eficaz? Marque as corretas.$t$, $j${"opcoes": [{"id": "a", "texto": "Cumprindo uma visão (sonho) definida e clara para o líder e para a equipe."}, {"id": "b", "texto": "Multiplicando de forma desorganizada."}, {"id": "c", "texto": "Cumprindo uma missão (estratégia) definida e clara."}, {"id": "d", "texto": "Colocando sonhos particulares acima dos da equipe."}, {"id": "e", "texto": "Com os doze trabalhando em unidade."}]}$j$::jsonb, $j$["a", "c", "e"]$j$::jsonb, $t$Itens 2.1, 2.2 e 2.3.$t$, 1) on conflict (aula_id, ordem) do nothing;
insert into public.escola_questoes(aula_id, ordem, tipo, enunciado, dados, gabarito, explicacao, pontos) values (19, 7, 'aberta', $t$Conte sua experiência de multiplicação pela Equipe Modelo.$t$, $j${}$j$::jsonb, $j${"referencia": "Resposta pessoal."}$j$::jsonb, null, 1) on conflict (aula_id, ordem) do nothing;
